 oil:c=>{c.fillStyle='#14101f';c.fillRect(0,0,256,256);for(const [x,y,col] of [[50,60,'#ff4fb8'],[170,40,'#46ffb0'],[210,170,'#4d7bff'],[80,190,'#c46bff'],[130,120,'#ffd35c']]){const g=c.createRadialGradient(x,y,2,x,y,95);g.addColorStop(0,col+'ee');g.addColorStop(1,col+'00');c.fillStyle=g;c.fillRect(0,0,256,256)}},
