 const glow=(parent,color,size,opacity=.7,position=[0,0,0])=>{const s=new T.Sprite(new T.SpriteMaterial({map:softGlow(),color,transparent:true,opacity,blending:T.AdditiveBlending,depthWrite:false,toneMapped:false}));s.scale.set(size,size,1);s.position.fromArray(position);parent.add(s);return s};
