 function localBox(object,exact){
  const box=new T.Box3(),pos=object.geometry?.attributes?.position;if(!pos)return box;inverseRoot.copy(root.matrixWorld).invert();toRoot.multiplyMatrices(inverseRoot,object.matrixWorld);
  if(exact){for(let i=0;i<pos.count;i++)box.expandByPoint(corner.fromBufferAttribute(pos,i).applyMatrix4(toRoot));return box}
  if(!object.geometry.boundingBox)object.geometry.computeBoundingBox();const g=object.geometry.boundingBox;
  for(const x of [g.min.x,g.max.x])for(const y of [g.min.y,g.max.y])for(const z of [g.min.z,g.max.z])box.expandByPoint(corner.set(x,y,z).applyMatrix4(toRoot));return box;
 }
