  cone(hat,col){const m=material(col,{rough:.55,metal:.05});add(new T.ConeGeometry(.17,.42,16),m,[0,.22,0],hat);for(const y of [.14,.26]){add(new T.CylinderGeometry(.158-(y-.14)*.45,.158-(y-.14)*.45+.012,.045,16),material('#ffffff',{rough:.5,metal:0,glow:.15}),[0,y,0],hat)}add(new T.BoxGeometry(.4,.025,.4),material(tone(col,-.25),{rough:.6,metal:0}),[0,.012,0],hat)},
  propeller(hat,col){const colors=[col,'#ffffff',tone(col,-.25),'#ffffff'];for(let i=0;i<4;i++)add(new T.SphereGeometry(.22,10,8,i*Math.PI/2,Math.PI/2,0,Math.PI/2),material(colors[i],{rough:.5,metal:.05,side:T.DoubleSide}),[0,0,0],hat).scale.y=.65;add(new T.CylinderGeometry(.012,.012,.1,6),material('#d9d9d9'),[0,.17,0],hat);const prop=new T.Group();prop.position.y=.225;hat.add(prop);for(const a of [0,Math.PI/2]){const blade=add(new T.BoxGeometry(.4,.01,.06),material(a?col:'#fff7a8',{rough:.4,metal:.2}),[0,0,0],prop);blade.rotation.y=a}animate(t=>{prop.rotation.y=t*14})},
  chef(hat,col){const m=material(col,{rough:.7,metal:0});add(new T.CylinderGeometry(.18,.17,.12,18),m,[0,.06,0],hat);for(const [x,y,z,r] of [[0,.22,0,.17],[.1,.17,.08,.13],[-.1,.17,.08,.13],[.09,.17,-.09,.13],[-.09,.17,-.09,.13],[0,.3,0,.11]])add(new T.SphereGeometry(r,12,9),m,[x,y,z],hat);add(new T.CylinderGeometry(.182,.182,.03,18),material(tone(col,-.3),{rough:.6,metal:0}),[0,.09,0],hat)},
  tophat(hat,col){const m=material(col,{rough:.35,metal:.25});const brim=add(new T.CylinderGeometry(.3,.3,.02,26),m,[0,.01,0],hat);brim.scale.z=1.1;add(new T.CylinderGeometry(.185,.2,.34,22),m,[0,.19,0],hat);add(new T.CylinderGeometry(.205,.205,.07,22),material('#d92b3a',{rough:.45,metal:.1}),[0,.065,0],hat);add(new T.BoxGeometry(.065,.075,.012),material('#ffd166',{metal:.9,rough:.2}),[0,.065,.205],hat)},
  bunny(hat,col){for(const s of [-1,1]){const ear=new T.Group();ear.position.set(s*.11,.02,0);ear.rotation.z=-s*.18;hat.add(ear);const outer=add(new T.CapsuleGeometry(.055,.4,4,10),material(col,{rough:.8,metal:0}),[0,.27,0],ear);outer.scale.z=.6;const inner=add(new T.CapsuleGeometry(.032,.3,4,8),material('#ffb3cf',{rough:.8,metal:0}),[0,.27,.026],ear);inner.scale.z=.5;animate(t=>{ear.rotation.z=-s*(.18+Math.sin(t*2.2+s)*.05)})}add(new T.SphereGeometry(.07,10,8),material(col,{rough:.8,metal:0}),[0,0,0],hat)},
  cat(hat,col){for(const s of [-1,1]){const ear=new T.Group();ear.position.set(s*.17,.01,0);ear.rotation.z=-s*.28;hat.add(ear);add(new T.ConeGeometry(.095,.22,3),material(tone(col,-.15),{rough:.7,metal:0}),[0,.11,0],ear);const inner=add(new T.ConeGeometry(.058,.15,3),material('#ff8fb8',{rough:.7,metal:0}),[0,.09,.018],ear)}const band=add(new T.TorusGeometry(.17,.015,6,22,Math.PI),material(tone(col,-.3),{rough:.5,metal:.1}),[0,0,0],hat);band.rotation.set(0,0,0)},
  shark(hat,col){const shape=new T.Shape();shape.moveTo(-.26,0);shape.bezierCurveTo(-.12,.12,.04,.3,.16,.42);shape.bezierCurveTo(.14,.2,.22,.08,.3,0);shape.closePath();const fin=add(new T.ExtrudeGeometry(shape,{depth:.045,bevelEnabled:false}),material(col,{rough:.35,metal:.25}),[-.0225,.0,0],hat);fin.rotation.y=-Math.PI/2;fin.position.set(-.0225,0,0);add(new T.BoxGeometry(.048,.012,.4),material('#e8f4ff',{rough:.4,metal:.1}),[0,.004,.02],hat)},
  wizard(hat,col){const m=material(col,{rough:.6,metal:.05});const brim=add(new T.CylinderGeometry(.34,.34,.018,26),m,[0,.01,0],hat);brim.scale.z=1.1;add(new T.ConeGeometry(.2,.32,18),m,[0,.17,0],hat);const tip=add(new T.ConeGeometry(.12,.3,16),m,[.025,.4,0],hat);tip.rotation.z=-.35;add(new T.CylinderGeometry(.205,.21,.05,18),material('#ffd166',{rough:.3,metal:.8}),[0,.06,0],hat);const stars=[];for(const [x,y,z] of [[.1,.16,.17],[-.12,.22,.12],[.06,.3,-.12],[-.07,.12,-.19]]){const s=add(new T.OctahedronGeometry(.03),material('#fff3a3',{glow:1,metal:0}),[x,y,z],hat);stars.push(s)}animate(t=>stars.forEach((s,i)=>{s.scale.setScalar(.8+Math.sin(t*4+i*1.7)*.35);s.rotation.y=t*2}))},
  antenna(hat,col){const m=material(col,{rough:.3,metal:.8});add(new T.CylinderGeometry(.075,.095,.04,14),m,[0,.02,0],hat);add(new T.CylinderGeometry(.012,.014,.3,8),m,[0,.19,0],hat);const dish=new T.Group();dish.position.set(0,.3,0);dish.rotation.x=-.5;hat.add(dish);const bowl=add(new T.SphereGeometry(.13,16,8,0,Math.PI*2,0,Math.PI/2),material(tone(col,.15),{rough:.25,metal:.85,side:T.DoubleSide}),[0,0,0],dish);bowl.rotation.x=Math.PI/2;bowl.position.z=.02;add(new T.CylinderGeometry(.006,.006,.12,5),m,[0,0,.09],dish).rotation.x=Math.PI/2;const led=add(new T.SphereGeometry(.022,8,6),material('#ff4040',{glow:1,metal:0}),[0,.37,0],hat);animate(t=>{dish.rotation.y=Math.sin(t*.8)*.8;led.material.emissiveIntensity=Math.sin(t*6)>0?1.3:.1})},
  devil(hat,col){const m=material(col,{rough:.35,metal:.2,glow:.25});for(const s of [-1,1]){const horn=new T.Group();horn.position.set(s*.15,.02,0);horn.rotation.z=-s*.25;hat.add(horn);add(new T.ConeGeometry(.055,.17,10),m,[0,.08,0],horn);const mid=add(new T.ConeGeometry(.04,.15,10),m,[-s*.025,.2,0],horn);mid.rotation.z=s*.42;const tip=add(new T.ConeGeometry(.026,.12,8),material(tone(col,.35),{glow:.6,metal:0}),[-s*.07,.31,0],horn);tip.rotation.z=s*.85}},
  laurel(hat,col){const m=material(col,{rough:.4,metal:.45});for(let i=0;i<13;i++){const a=-Math.PI*.82+i/12*Math.PI*1.64+Math.PI/2,side=i<6.5?-1:1;for(const o of [0,1]){const leaf=add(new T.SphereGeometry(.05,8,6),m,[Math.cos(a)*(.25-o*.01),.02+o*.02,Math.sin(a)*(.25-o*.01)],hat);leaf.scale.set(1,.22,.55);leaf.rotation.y=-a+(o?.5:-.5)*side;leaf.rotation.z=.3*(o?1:-1)}}add(new T.TorusGeometry(.252,.007,5,40,Math.PI*1.65),material(tone(col,-.3),{metal:.6}),[0,.02,0],hat).rotation.x=Math.PI/2},
