  icecrown(hat,col){const m=material(col,{rough:.05,metal:.15,glow:.4,opacity:.82});add(new T.CylinderGeometry(.19,.2,.06,16,1,true),material(tone(col,.2),{rough:.1,metal:.3,glow:.3,side:T.DoubleSide}),[0,.03,0],hat);for(let i=0;i<7;i++){const a=i*Math.PI*2/7,h=.26+(i%2)*.14,p=add(new T.OctahedronGeometry(.07),m,[Math.sin(a)*.18,.06+h/2,Math.cos(a)*.18],hat);p.scale.set(.8,h/.14,.8);p.rotation.y=a}const shards=[];for(let i=0;i<5;i++)shards.push(add(new T.OctahedronGeometry(.025),material('#ffffff',{glow:1,metal:0}),[0,.3,0],hat));glow(hat,col,.9,.4,[0,.18,0]);animate(t=>shards.forEach((s,i)=>{const a=t*1.4+i*1.256;s.position.set(Math.cos(a)*.26,.22+Math.sin(t*2+i)*.06,Math.sin(a)*.26);s.rotation.set(t*2,t*3,0)}))},
